using System;using System.Collections.Generic;using System.Data;using System.Linq;using System.Threading.Tasks;using Autodesk.Navisworks.Api;using NavisLegacyPlugin.Models;using NavisLegacyPlugin.Models.Execution;using NavisLegacyPlugin.Models.ExternalSources;using NavisLegacyPlugin.Models.Matching;using NavisLegacyPlugin.Services.DataSources;using NavisLegacyPlugin.Services.Execution;using NavisLegacyPlugin.Services.ExternalSources;using NavisLegacyPlugin.Services.Lookups;using NavisLegacyPlugin.Services.Mappers;using NavisLegacyPlugin.Services.Matching;using NavisLegacyPlugin.Services.Topology;
namespace NavisLegacyPlugin.Services
{
 public class DataPaintingService
 {
  private readonly ModelLookupService _lookupService;private readonly ExecuteSignatureExecutor _executor;private readonly ComPropertyWriteService _writer;
  public DataPaintingService(ModelLookupService lookupService,ExecuteSignatureExecutor executor):this(lookupService,executor,new ComPropertyWriteService()){} public DataPaintingService(ModelLookupService lookupService,ExecuteSignatureExecutor executor,ComPropertyWriteService writer){_lookupService=lookupService;_executor=executor;_writer=writer;}
  public async Task<(int matched,int unmatched)> ExecuteAsync(IDataSource d,MappingConfig m,LookupConfig l,WriteConfig w,ProgressConfig p){var r=await _executor.ExecuteAsync(new ExecuteSignature(d,new MappingConfigStrategy(m),new ModelPropertyLookupProvider(_lookupService,l),w,p));return(r.Matched,r.Unmatched);} public Task<(int matched,int unmatched)> ExecuteAsync(IDataSource d,MappingConfig m,Dictionary<string,ModelItem> l,WriteConfig w,ProgressConfig p){return ExecuteAsync(d,m,l,w,p,null);} public async Task<(int matched,int unmatched)> ExecuteAsync(IDataSource d,MappingConfig m,Dictionary<string,ModelItem> l,WriteConfig w,ProgressConfig p,ExecutionSelectionSets s){var r=await _executor.ExecuteAsync(new ExecuteSignature(d,new MappingConfigStrategy(m),new DictionaryLookupProvider(l),w,p,s));return(r.Matched,r.Unmatched);}
  public async Task<ExecuteResult> ExecuteExternalSourceAsync(ExternalExportPopulationResponse response,MappingConfig mapping,Dictionary<string,ModelItem> targetLookup,IEnumerable<ModelItem> targetItems,WriteConfig writeConfig,ProgressConfig progress,ExecutionSelectionSets selectionSets,MatchingStrategyMode matchingStrategy,AnchorMethod anchorMethod)
  {
   var adapter=new ExternalSourcePopulationAdapter();var population=adapter.Adapt(response);DataTable table=adapter.ToDataTable(population);MatchStrategyDefinition strategy=Create(anchorMethod);
   if(matchingStrategy==MatchingStrategyMode.Direct){var signature=new ExecuteSignature(new InMemoryDataSource(table),new MappingConfigStrategy(mapping),new DictionaryLookupProvider(targetLookup),writeConfig,progress,selectionSets);var resolver=new OrderedRowMatchResolver(targetItems??Enumerable.Empty<ModelItem>(),new[]{strategy});ExecuteResult direct=await _executor.ExecuteAsync(signature,population,resolver);return new ExecuteResult(new TransferOutcomeSet(direct.Outcomes.ExecutionId,direct.Outcomes.SourceFile,direct.Outcomes.ExportSet,direct.Outcomes.SourceResolution,direct.Outcomes.TargetResolution,direct.Outcomes.Status,direct.Outcomes.Outcomes,matchingStrategy.ToString(),anchorMethod.ToString()));}
   progress.ProgressText?.Report("Analysing topology...");var topo=new ExternalTopologyTransferCoordinator(_writer).Execute(population,table,targetItems,strategy,writeConfig.Overwrite);var outcomes=new List<TransferOutcome>();for(int i=0;i<population.Items.Count;i++){var s=population.Items[i];var t=topo.FirstOrDefault(x=>x.RowIndex==i);var payload=(s.Properties??new List<ExternalPropertySnapshot>()).Select(x=>new TransferPayloadValue((x.Category??string.Empty)+"."+(x.Name??string.Empty),x.Value)).ToList();var source=new TransferSourceIdentity(i,s.InstanceGuid,Prop(s,"Item","GUID"),SourceFile(s),s.DisplayName);var match=t==null?new TransferMatchResult(TransferMatchStatus.MissingKey,strategy.Name,string.Empty,"No topology row was produced.",null):t.Match;outcomes.Add(new TransferOutcome(source,payload,match,t==null?null:t.Operations,t==null?null:t.Resolution,t!=null&&t.Conflict));}var status=outcomes.Any(x=>x.OperationStatus==TransferOperationStatus.Failed)?TransferExecutionStatus.CompletedWithFailures:TransferExecutionStatus.Completed;var set=new TransferOutcomeSet(Guid.NewGuid().ToString("D"),population.SourceFile,population.ExportSetName,population.ResolutionType,selectionSets?.TargetResolutionType.ToString(),status,outcomes,matchingStrategy.ToString(),anchorMethod.ToString());progress.ProgressPercent?.Report(100);progress.ProgressText?.Report("Complete.");return new ExecuteResult(set);
  }
  private static MatchStrategyDefinition Create(AnchorMethod a){switch(a){case AnchorMethod.ItemGuid:return MatchStrategyFactory.ItemGuid(0);case AnchorMethod.IfcGuid:return MatchStrategyFactory.IfcGuid(0);case AnchorMethod.IfcGuidAndDisplayName:return MatchStrategyFactory.IfcGuidAndDisplayName(0);default:return MatchStrategyFactory.ItemGuidAndFilename(0);}} private static string Prop(ExternalModelItemSnapshot s,string c,string n){var p=s.Properties.FirstOrDefault(x=>x!=null&&string.Equals(x.Category,c,StringComparison.OrdinalIgnoreCase)&&string.Equals(x.Name,n,StringComparison.OrdinalIgnoreCase));return p==null?string.Empty:p.Value;}private static string SourceFile(ExternalModelItemSnapshot s){string x=Prop(s,"Item","Source File Name");return string.IsNullOrWhiteSpace(x)?Prop(s,"Item","Source File"):x;}
 }
}
